-- 017_add_50_more_native_species.sql
-- LOCAL-ONLY migration for the Katutubong Puno project.
-- Adds a second researched batch of 50 Philippine native/endemic tree species.
-- No record in this batch overlaps the 117 active accepted names present after 016.
-- Do not apply to the live VPS before explicit deployment review.
--
-- Transaction handling: the project migration runner wraps each migration in a
-- transaction. For manual use: psql --single-transaction --set ON_ERROR_STOP=1.

SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '5min';

CREATE TEMP TABLE _species_017_input (
  desired_id uuid, scientific_name text, genus text, species_epithet text,
  family text, native_status text, description text, leaf_description text,
  bark_description text, flower_description text, fruit_description text,
  seed_description text, growth_form text, min_height_m numeric,
  max_height_m numeric, min_canopy_m numeric, max_canopy_m numeric,
  growth_rate text, fruit_bearing boolean, flowering boolean,
  conservation_status text, conservation_source text,
  distribution_notes text, habitat_notes text
) ON COMMIT DROP;

INSERT INTO _species_017_input VALUES
  ('efe85696-5524-5750-9abb-df75ce8f44c8', 'Anisoptera costata', 'Anisoptera', 'costata', 'Dipterocarpaceae', 'native', 'Anisoptera costata is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Known from one record from Zamboanga. Primary lowland forest. 0-700m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Borneo, Cambodia, Java, Malay Peninsula, Myanmar, Philippines, Sumatra, Thailand, Vietnam. MINDANAO: Zamboanga.', 'Known from one record from Zamboanga. Primary lowland forest. 0-700m.'),
  ('2d985e28-556a-5f8e-84d2-5d831ee56e9a', 'Dipterocarpus eurhynchus', 'Dipterocarpus', 'eurhynchus', 'Dipterocarpaceae', 'native', 'Dipterocarpus eurhynchus is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Local, on undulating land in lowland primary dipterocarp forest. Rare. 0-700m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Borneo, Malay Peninsula, Philippines, Sumatra. BASILAN.', 'Local, on undulating land in lowland primary dipterocarp forest. Rare. 0-700m.'),
  ('bca269a3-c0e1-505c-8699-d18ddfdce9f9', 'Dipterocarpus hasseltii', 'Dipterocarpus', 'hasseltii', 'Dipterocarpaceae', 'native', 'Dipterocarpus hasseltii is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Hasselt''s panau. Primary forests at low and medium elevation. 0-1000m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Borneo, Java, Lesser Sunda Isls, Malay Peninsula, Philippines, Sumatra, Thailand. BASILAN, BILIRAN, BOHOL, LEYTE, LUZON: Cagayan, Camarines, Ilocos Norte, Isabela, Laguna, Nueva Ecija, Nueva Vizcaya, Quezon, MINDANAO: Agusan del Norte, Surigao, Zamboanga, NEGROS, PALAWAN.', 'Hasselt''s panau. Primary forests at low and medium elevation. 0-1000m.'),
  ('42c58aa9-3439-5dca-aee9-d8441f5c9c0f', 'Dipterocarpus kerrii', 'Dipterocarpus', 'kerrii', 'Dipterocarpaceae', 'native', 'Dipterocarpus kerrii is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Malapanau. On lateritic soils in seasonally dry primary dipterocarp forests. Frequently gregarious. 0-800m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Andaman Isls, Borneo, Malay Peninsula, Myanmar, Philippines, Sumatra, Thailand. LUZON: Albay, Cagayan, Camarines, Camarines Sur, Laguna, Nueva Ecija, Quezon, Sorsogon, MINDANAO: Agusan del Norte, Davao, Davao del Norte, Surigao, Surigao del Sur, Zamboanga, MINDORO, SAMAR, SULU ARCHIPELAGO, TAWI-TAWI.', 'Malapanau. On lateritic soils in seasonally dry primary dipterocarp forests. Frequently gregarious. 0-800m.'),
  ('5233ad1d-9f28-53ec-910f-e1559d097007', 'Dipterocarpus kunstleri', 'Dipterocarpus', 'kunstleri', 'Dipterocarpaceae', 'native', 'Dipterocarpus kunstleri is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Broad-winged apitong. Primary lowland forests, on undulating or flat land, especially near streams.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Borneo, Malay Peninsula, Philippines, Sumatra. BASILAN, LEYTE, LUZON: Albay, Aurora, Cagayan, Camarines, Isabela, Laguna, Quezon, MINDANAO: Agusan, Davao, Surigao, Surigao del Sur, NEGROS, POLILLO, SAMAR.', 'Broad-winged apitong. Primary lowland forests, on undulating or flat land, especially near streams.'),
  ('5c458560-0781-551d-9746-23620cc95373', 'Dipterocarpus pseudocornutus', 'Dipterocarpus', 'pseudocornutus', 'Dipterocarpaceae', 'endemic', 'Dipterocarpus pseudocornutus is a Philippine endemic tree in Dipterocarpaceae. CDFP habitat record: The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. TAWI-TAWI.', 'The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.'),
  ('160512d8-5832-582f-b441-50ea4618037d', 'Dipterocarpus orbicularis', 'Dipterocarpus', 'orbicularis', 'Dipterocarpaceae', 'native', 'Dipterocarpus orbicularis is a Philippine native tree in Dipterocarpaceae. CDFP habitat record: Lowland mixed dipterocarp forest. Resembles Dipterocarpus grandiflorus Blanco in fruit and Dipterocarpus gracilis Blume in the indumentum.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, NULL, 'No global category stated in the CDFP record consulted', 'Borneo, Philippines. LUZON: Camarines Norte.', 'Lowland mixed dipterocarp forest. Resembles Dipterocarpus grandiflorus Blanco in fruit and Dipterocarpus gracilis Blume in the indumentum.'),
  ('4a2e49c8-1e92-5bb4-b899-6f71eda2e762', 'Hopea loheriana', 'Hopea', 'loheriana', 'Dipterocarpaceae', 'endemic', 'Hopea loheriana is a Philippine endemic tree in Dipterocarpaceae. CDFP habitat record: The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution. The accepted-name record was retained from CDFP; the automated Kew exact-name search did not return a direct match, so future taxonomic review is flagged.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. LUZON: Rizal.', 'The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.'),
  ('81f6d2ed-691d-5ef9-8c29-0306cdf61f68', 'Hopea reynosoi', 'Hopea', 'reynosoi', 'Dipterocarpaceae', 'endemic', 'Hopea reynosoi is a Philippine endemic tree in Dipterocarpaceae. CDFP habitat record: The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Endemic to the Philippines. SAMAR.', 'The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.'),
  ('d10f9931-f55a-51d2-a0e2-c4c1163a0315', 'Hopea samarensis', 'Hopea', 'samarensis', 'Dipterocarpaceae', 'endemic', 'Hopea samarensis is a Philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Mixed dipterocarp forests in moist lowland valleys.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Endemic to the Philippines. SAMAR.', 'Mixed dipterocarp forests in moist lowland valleys.'),
