  ('0c910e45-57f7-5923-bddd-867a8666806b', 'Garcinia samarensis', 'Garcinia', 'samarensis', 'Clusiaceae', 'endemic', 'Garcinia samarensis is a Philippine endemic tree in Clusiaceae. CDFP habitat record: Damp primary forests at low elevation. The accepted-name record was retained from CDFP; the automated Kew exact-name search did not return a direct match, so future taxonomic review is flagged.', 'Leaves are opposite, simple, entire, and leathery, with close parallel side veins.', 'Cut bark and twigs produce yellowish latex, an important Garcinia field character.', 'Small thick-petaled flowers may be male or female and occur singly or in short clusters.', 'The fruit is a fleshy berry with a persistent calyx; mature color and surface texture help distinguish species.', 'Several large seeds are usually surrounded by pulp.', 'medium', 8, 25, 4, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. SAMAR.', 'Damp primary forests at low elevation.'),
  ('7d00281c-d252-54fd-848e-50af4635da56', 'Elaeocarpus argenteus', 'Elaeocarpus', 'argenteus', 'Elaeocarpaceae', 'native', 'Elaeocarpus argenteus is a Philippine native tree in Elaeocarpaceae. CDFP habitat record: 600-2250m.', 'Leaves are simple and alternate, usually with a toothed margin; older leaves may redden before falling.', 'Bark is gray to brown and may become shallowly fissured or scaly with age.', 'Small pale flowers hang in clusters and commonly have finely divided or fringed petals.', 'The fruit is a drupe, often blue, purple, or dark at maturity, with a firm sculptured stone.', 'One or more seeds are enclosed within the hard stone and are commonly dispersed by wildlife.', 'medium', 8, 30, 4, 14, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Philippines, Taiwan. CAMIGUIN, LUZON: Apayao (photos), Aurora, Benguet, Camarines Sur, Ifugao, Laguna, Mountain Province, Nueva Ecija (photos), Nueva Vizcaya, Pampanga, Quezon, Rizal, Sorsogon, Zambales, MINDANAO: Bukidnon (photos), Davao, Davao Oriental, Davao del Sur, Misamis, Misamis Oriental (photos), Surigao del Norte, MINDORO, NEGROS, SIBUYAN.', '600-2250m.'),
  ('0575b303-f16b-5be7-a54b-5426b20c9cdc', 'Elaeocarpus dinagatensis', 'Elaeocarpus', 'dinagatensis', 'Elaeocarpaceae', 'endemic', 'Elaeocarpus dinagatensis is a Philippine endemic tree in Elaeocarpaceae. CDFP habitat record: L.L.Co: Both islands have predominantly ultramafic geology. Low elevation. Fr. May-Jun.', 'Leaves are simple and alternate, usually with a toothed margin; older leaves may redden before falling.', 'Bark is gray to brown and may become shallowly fissured or scaly with age.', 'Small pale flowers hang in clusters and commonly have finely divided or fringed petals.', 'The fruit is a drupe, often blue, purple, or dark at maturity, with a firm sculptured stone.', 'One or more seeds are enclosed within the hard stone and are commonly dispersed by wildlife.', 'medium', 8, 30, 4, 14, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Endemic to the Philippines. BUCAS GRANDE, DINAGAT.', 'L.L.Co: Both islands have predominantly ultramafic geology. Low elevation. Fr. May-Jun.'),
  ('d91126c7-265a-54db-aa37-0226a65cdc73', 'Elaeocarpus gitingensis', 'Elaeocarpus', 'gitingensis', 'Elaeocarpaceae', 'endemic', 'Elaeocarpus gitingensis is a Philippine endemic tree in Elaeocarpaceae. CDFP habitat record: Lowland forest. 225m.', 'Leaves are simple and alternate, usually with a toothed margin; older leaves may redden before falling.', 'Bark is gray to brown and may become shallowly fissured or scaly with age.', 'Small pale flowers hang in clusters and commonly have finely divided or fringed petals.', 'The fruit is a drupe, often blue, purple, or dark at maturity, with a firm sculptured stone.', 'One or more seeds are enclosed within the hard stone and are commonly dispersed by wildlife.', 'medium', 8, 30, 4, 14, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. SIBUYAN.', 'Lowland forest. 225m.'),
  ('5a6a4f62-7778-5739-9d55-1aed5ab8ee34', 'Elaeocarpus mindoroensis', 'Elaeocarpus', 'mindoroensis', 'Elaeocarpaceae', 'endemic', 'Elaeocarpus mindoroensis is a Philippine endemic tree in Elaeocarpaceae. CDFP habitat record: The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.', 'Leaves are simple and alternate, usually with a toothed margin; older leaves may redden before falling.', 'Bark is gray to brown and may become shallowly fissured or scaly with age.', 'Small pale flowers hang in clusters and commonly have finely divided or fringed petals.', 'The fruit is a drupe, often blue, purple, or dark at maturity, with a firm sculptured stone.', 'One or more seeds are enclosed within the hard stone and are commonly dispersed by wildlife.', 'medium', 8, 30, 4, 14, 'moderate', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. MINDORO, PANAY.', 'The CDFP checklist record gives no additional habitat sentence beyond its Philippine distribution.'),
  ('3afa8cfe-aac1-5a21-b114-c40de0cabb6b', 'Terminalia macrantha', 'Terminalia', 'macrantha', 'Combretaceae', 'endemic', 'Terminalia macrantha is a Philippine endemic tree in Combretaceae. CDFP habitat record: Summit of flat ridge, locally common. 300m.', 'Simple leaves are alternate but often crowded near twig ends; shape, base glands, and lower-surface hairs help distinguish species.', 'Older bark is gray to brown and commonly becomes fissured or scaly.', 'Small flowers lacking showy petals are grouped in spikes or short panicles.', 'The fruit is a fleshy to firm, often flattened or ridged drupe; mature color and cross-section are useful characters.', 'A single seed is protected by the hard inner layer of the fruit.', 'large', 15, 35, 7, 18, 'moderate', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Endemic to the Philippines. SAMAR.', 'Summit of flat ridge, locally common. 300m.'),
  ('03264cfb-7f6b-5630-a8c1-3a741254096f', 'Terminalia surigaensis', 'Terminalia', 'surigaensis', 'Combretaceae', 'endemic', 'Terminalia surigaensis is a Philippine endemic tree in Combretaceae. CDFP habitat record: Along streams at low elevation. (?-)300m.', 'Simple leaves are alternate but often crowded near twig ends; shape, base glands, and lower-surface hairs help distinguish species.', 'Older bark is gray to brown and commonly becomes fissured or scaly.', 'Small flowers lacking showy petals are grouped in spikes or short panicles.', 'The fruit is a fleshy to firm, often flattened or ridged drupe; mature color and cross-section are useful characters.', 'A single seed is protected by the hard inner layer of the fruit.', 'large', 15, 35, 7, 18, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Endemic to the Philippines. DINAGAT, HOMONHON, MINDANAO: Bukidnon, Surigao del Norte, Surigao del Sur.', 'Along streams at low elevation. (?-)300m.'),
  ('7c614e32-442a-58b9-8d6e-67800b81ba12', 'Dillenia bolsteri', 'Dillenia', 'bolsteri', 'Dilleniaceae', 'endemic', 'Dillenia bolsteri is a Philippine endemic tree in Dilleniaceae. CDFP habitat record: We follow Fernando et al. (2017) in considering Dillenia bolsteri distinct from Dillenia cauliflora. 50-450m (photos).', 'Leaves are large, alternate, prominently parallel-veined, and usually toothed, with a rough or corrugated appearance.', 'Bark is gray-brown and becomes shallowly fissured or flaky on older stems.', 'Large flowers have five broad petals and many yellow stamens, making flowering trees conspicuous.', 'The rounded aggregate fruit is enclosed by enlarged, persistent sepals.', 'Numerous small seeds are embedded in the fruit pulp.', 'medium', 8, 20, 5, 12, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. DINAGAT, HINATUAN, LUZON: Apayao (photos), MINDANAO: Surigao del Norte, Surigao del Sur (photos), SAMAR.', 'We follow Fernando et al. (2017) in considering Dillenia bolsteri distinct from Dillenia cauliflora. 50-450m (photos).'),
  ('8cfeade8-9255-5f4e-b59b-e3445d4b8e04', 'Magnolia philippinensis', 'Magnolia', 'philippinensis', 'Magnoliaceae', 'native', 'Magnolia philippinensis is a Philippine native tree in Magnoliaceae. CDFP habitat record: Midmontane forests. Fl. & fr. Jan-Feb. Commonly cultivated in tropical and subtropical countries. 0-2730m.', 'Leaves are simple, alternate, entire, and often leathery; buds are enclosed by stipules that leave ring-like scars around the twigs.', 'Bark is gray to brown and the twigs may be aromatic when bruised.', 'Large, fragrant flowers have numerous tepals, stamens, and separate carpels arranged on an elongated receptacle.', 'The aggregate fruit is cone-like and made of many follicles that open when mature.', 'Seeds commonly hang briefly by fine threads and may have a brightly colored outer covering attractive to birds.', 'large', 10, 30, 5, 15, 'moderate', TRUE, TRUE, 'Data Deficient', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Philippines, Thailand. CEBU, LUZON: Abra, Bataan, Batangas, Benguet, Ilocos Norte, Laguna, Mountain Province, Nueva Vizcaya (photos), Quezon, Rizal, Zambales, MINDANAO: Bukidnon, Davao del Sur, Lanao, Misamis Occidental, NEGROS.', 'Midmontane forests. Fl. & fr. Jan-Feb. Commonly cultivated in tropical and subtropical countries. 0-2730m.'),
  ('8360e6c0-8213-5be6-b51f-6caae4d8f909', 'Dacrycarpus imbricatus', 'Dacrycarpus', 'imbricatus', 'Podocarpaceae', 'native', 'Dacrycarpus imbricatus is a Philippine native tree in Podocarpaceae. CDFP habitat record: (200-)700-3000m.', 'Evergreen foliage ranges from narrow flattened leaves to scale-like leaves depending on shoot age; leaf form and arrangement are diagnostic.', 'Mature bark becomes fibrous, flaky, or fissured and should be compared with verified conifer material.', 'There are no true flowers; separate pollen cones and seed-bearing structures are produced.', 'The seed-bearing structure is not a true fruit; a single seed develops above or within a fleshy receptacle or covering.', 'The single seed is associated with a fleshy, animal-dispersed structure; use fresh seed from a verified native population.', 'large', 10, 35, 5, 15, 'slow', FALSE, FALSE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Borneo, China, Malay Peninsula, Moluccas, Myanmar, New Guinea, Pacific Ocean, Philippines, Sulawesi, Sumatra. LUZON: Abra, Bataan, Benguet, Ifugao, Ilocos Sur, Laguna, Mountain Province, Nueva Vizcaya, Quezon, Zambales, MINDANAO: Bukidnon, Cotabato, Davao, Davao Oriental, Davao del Sur, Misamis, Misamis Occidental, South Cotabato, MINDORO, NEGROS, PANAY.', '(200-)700-3000m.'),
  ('3cd8c0f4-aab6-5b15-869a-351dc38d9ed0', 'Podocarpus costalis', 'Podocarpus', 'costalis', 'Podocarpaceae', 'native', 'Podocarpus costalis is a Philippine native tree in Podocarpaceae. CDFP habitat record: Coastal bluffs. 0-300(-?)m.', 'Evergreen foliage ranges from narrow flattened leaves to scale-like leaves depending on shoot age; leaf form and arrangement are diagnostic.', 'Mature bark becomes fibrous, flaky, or fissured and should be compared with verified conifer material.', 'There are no true flowers; separate pollen cones and seed-bearing structures are produced.', 'The seed-bearing structure is not a true fruit; a single seed develops above or within a fleshy receptacle or covering.', 'The single seed is associated with a fleshy, animal-dispersed structure; use fresh seed from a verified native population.', 'large', 10, 35, 5, 15, 'slow', FALSE, FALSE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'BABUYAN ISLS, BATANES, LUZON: Ilocos Norte, Isabela, POLILLO.', 'Coastal bluffs. 0-300(-?)m.'),
  ('13b5cafb-7c1e-57e2-9732-7ce5479ff7c7', 'Nauclea robinsonii', 'Nauclea', 'robinsonii', 'Rubiaceae', 'endemic', 'Nauclea robinsonii is a Philippine endemic tree in Rubiaceae. CDFP habitat record: Low elevation secondary forests. 350-450m (photos).', 'Leaves are simple, opposite, and entire, with prominent side veins and interpetiolar stipules between the leaf stalks.', 'Bark is gray to brown and becomes rough or shallowly fissured on older trunks.', 'Numerous small flowers are packed into spherical heads, with projecting styles giving a brush-like appearance.', 'The fused flower head develops into a rounded multiple fruit made of many small fruitlets.', 'Numerous small seeds occur within the mature multiple fruit and are dispersed by water or animals.', 'large', 10, 30, 6, 16, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Endemic to the Philippines. LEYTE, LUZON: Quezon, MINDANAO: Agusan del Norte, Agusan del Sur, Surigao del Norte (photos), Surigao del Sur, PALAWAN, POLILLO, SAMAR.', 'Low elevation secondary forests. 350-450m (photos).');


DO $$
BEGIN
  IF (SELECT count(*) FROM _species_017_input) <> 50 THEN
    RAISE EXCEPTION '017 input must contain exactly 50 species';
  END IF;
  IF (SELECT count(DISTINCT lower(scientific_name)) FROM _species_017_input) <> 50 THEN
    RAISE EXCEPTION '017 input contains duplicate accepted scientific names';
  END IF;
END $$;

INSERT INTO species (
  id, scientific_name, genus, species_epithet, family, native_status,
  description, leaf_description, bark_description, flower_description,
  fruit_description, seed_description, growth_form, min_height_m,
  max_height_m, min_canopy_m, max_canopy_m, growth_rate, fruit_bearing,
  flowering, conservation_status, conservation_source, verification_status,
  verified_at, deleted_at
)
SELECT desired_id, scientific_name, genus, species_epithet, family, native_status,
       description, leaf_description, bark_description, flower_description,
       fruit_description, seed_description, growth_form, min_height_m,
       max_height_m, min_canopy_m, max_canopy_m, growth_rate, fruit_bearing,
       flowering, conservation_status, conservation_source, 'verified', now(), NULL
FROM _species_017_input
ON CONFLICT (scientific_name) DO UPDATE SET
  genus=EXCLUDED.genus, species_epithet=EXCLUDED.species_epithet,
  family=EXCLUDED.family, native_status=EXCLUDED.native_status,
  description=EXCLUDED.description, leaf_description=EXCLUDED.leaf_description,
  bark_description=EXCLUDED.bark_description, flower_description=EXCLUDED.flower_description,
  fruit_description=EXCLUDED.fruit_description, seed_description=EXCLUDED.seed_description,
  growth_form=EXCLUDED.growth_form, min_height_m=EXCLUDED.min_height_m,
  max_height_m=EXCLUDED.max_height_m, min_canopy_m=EXCLUDED.min_canopy_m,
  max_canopy_m=EXCLUDED.max_canopy_m, growth_rate=EXCLUDED.growth_rate,
  fruit_bearing=EXCLUDED.fruit_bearing, flowering=EXCLUDED.flowering,
  conservation_status=EXCLUDED.conservation_status,
  conservation_source=EXCLUDED.conservation_source,
  verification_status='verified', verified_at=now(), deleted_at=NULL;

CREATE TEMP TABLE _species_017 AS
SELECT s.id, i.* FROM _species_017_input i JOIN species s USING (scientific_name);

DELETE FROM species_names WHERE species_id IN (SELECT id FROM _species_017);
INSERT INTO species_names (id,species_id,name,name_type,is_primary)
SELECT v.id::uuid,s.id,v.name,'common',TRUE FROM (VALUES
  ('3fac21bc-7263-5edb-92b5-cbbcb1d41b78', 'Dipterocarpus hasseltii', 'Hasselt''s panau'),
